#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiQuery: FfiConverter {

    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = FfiQuery

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> FfiQuery {
        return FfiQuery(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: FfiQuery) -> UnsafeMutableRawPointer {
        return value.uniffiClonePointer()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiQuery {
        let v: UInt64 = try readInt(&buf)
        // The Rust code won't compile if a pointer won't fit in a UInt64.
        // We have to go via `UInt` because that's the thing that's the size of a pointer.
        let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: v))
        if (ptr == nil) {
            throw UniffiInternalError.unexpectedNullPointer
        }
        return try lift(ptr!)
    }

    public static func write(_ value: FfiQuery, into buf: inout [UInt8]) {
        // This fiddling is because `Int` is the thing that's the same size as a pointer.
        // The Rust code won't compile if a pointer won't fit in a `UInt64`.
        writeInt(&buf, UInt64(bitPattern: Int64(Int(bitPattern: lower(value)))))
    }
}




#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeFfiQuery_lift(_ pointer: UnsafeMutableRawPointer) throws -> FfiQuery {
    return try FfiConverterTypeFfiQuery.lift(pointer)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeFfiQuery_lower(_ value: FfiQuery) -> UnsafeMutableRawPointer {
    return FfiConverterTypeFfiQuery.lower(value)
}




public protocol FfiStoreProtocol : AnyObject {
    
    func archivedBlockCount() throws  -> UInt64
    
    func classCL2ResidentBytes()  -> UInt64
    
    func coinbaseFkAtHeights(heights: [UInt32]) throws  -> [FfiCoinbaseAtHeight]
    
    func datadirBytes()  -> UInt64
    
    func fenceMaxConnectedFk()  -> UInt64
    
    func fenceTipHeight()  -> UInt64?
    
    func flush() throws 
    
    func flushHeaderArchive() throws 
    
    func getFkByTxid(txidHex: String) throws  -> UInt64?
    
    func getFkByTxidBatch(txidsHex: [String]) throws  -> [UInt64?]
    
    func getFkByTxidTip(txidHex: String) throws  -> UInt64?
    
    func getHeader(fk: UInt64) throws  -> FfiHeaderRecord
    
    func getHeaderByHash(hashHex: String) throws  -> FfiHeaderRecord?
    
    func getTx(fk: UInt64) throws  -> FfiTxRecord
    
    func getTxByTxid(txidHex: String) throws  -> FfiTxRecord?
    
    func getTxFull(fk: UInt64) throws  -> FfiTxFull
    
    func getTxFullSpan(first: UInt64, last: UInt64) throws  -> [FfiTxFull]
    
    func getTxMetaAndOutputs(fk: UInt64) throws  -> FfiTxMetaAndOutputs
    
    func getTxMetaAndPrevouts(fk: UInt64) throws  -> FfiTxMetaAndPrevouts
    
    func hasConfirmedStrongSpenderCreate(createTxFk: UInt64, outIndex: UInt32, bodyRange: FfiTxRange?) throws  -> Bool
    
    func hasConfirmedStrongSpenderCreateAt(createTxFk: UInt64, outIndex: UInt32, bodyRange: FfiTxRange?, tip: UInt32?) throws  -> Bool
    
    func headerCount()  -> UInt64
    
    func headerSlots()  -> UInt64
    
    func heightFenceRunCount()  -> UInt64
    
    func isConfirmedStrong(txFk: UInt64) throws  -> Bool
    
    func isConfirmedStrongAt(txFk: UInt64, tip: UInt32?) throws  -> Bool
    
    func isSplit()  -> Bool
    
    func mtpTimesAt(height: UInt32)  -> FfiMtpTimes?
    
    func path()  -> String
    
    func rebuildHeightFence() throws 
    
    func resolveTxid(txidHex: String, tipThenAny: Bool) throws  -> UInt64?
    
    func spenderListCount()  -> UInt64
    
    func spendersCreate(createFk: UInt64, outIndex: UInt32) throws  -> [UInt64]
    
    func tipHeight()  -> UInt64?
    
    func txBodyRange(fk: UInt64) throws  -> FfiTxRange
    
    func txBodyRangeBatch(fks: [UInt64]) throws  -> [FfiTxRange?]
    
    func txCreateLocRangeBatch(fks: [UInt64]) throws  -> [FfiCreateLocPair?]
    
    func txHeadBits()  -> UInt32
    
    func txHeightGet(txFk: UInt64) throws  -> UInt32?
    
    func txHeightGetBatch(fks: [UInt64]) throws  -> [UInt32?]
    
    func txInwitRange(fk: UInt64) throws  -> FfiTxRange
    
    func txSpentRange(fk: UInt64) throws  -> FfiTxRange
    
    func txSpentRangeBatch(fks: [UInt64]) throws  -> [FfiTxRange?]
    
    func txidsGetMany(fks: [UInt64]) throws  -> [String?]
    
}

open class FfiStore:
    FfiStoreProtocol {
    fileprivate let pointer: UnsafeMutableRawPointer!

    /// Used to instantiate a [FFIObject] without an actual pointer, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoPointer {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
    required public init(unsafeFromRawPointer pointer: UnsafeMutableRawPointer) {
        self.pointer = pointer
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noPointer: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing [Pointer] the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noPointer: NoPointer) {
        self.pointer = nil
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiClonePointer() -> UnsafeMutableRawPointer {
        return try! rustCall { uniffi_rustylib_fn_clone_ffistore(self.pointer, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        guard let pointer = pointer else {
            return
        }

        try! rustCall { uniffi_rustylib_fn_free_ffistore(pointer, $0) }
    }

    
